const a={ocnal:{baipishu:"White Paper",home1:"Buka Dunia Mata Uang Digital",home2:"Deposit Sekarang",home3:"Nama",home4:"Harga",home5:"Perubahan 24h",home6:"Perdagangkan",home7:"Memulai",home8:"Buat akun",home9:"Daftarkan akun untuk menikmati lebih banyak hak istimewa dan layanan",home10:"Daftar",home11:"Deposit Dana",home12:"Isi akun Anda dan mulai berinvestasi dalam cryptocurrency",home13:"Deposit kripto",home14:"Mulai berdagang",home15:"Jual, beli atau salin perdagangan, temukan lebih banyak",home16:"Jelajahi pasar",home17:"Pasar cryptocurrency sedang berkembang pesat, mencakup mata uang digital, teknologi blockchain, dan lainnya. Prospeknya menjanjikan, tetapi investasi membutuhkan kehati-hatian.",home18:"Spot",home19:"Perdagangan waktu nyata di pasar spot dengan perubahan harga yang cepat.",home20:"Kontrak abadi",home21:"Perdagangan kontrak menyediakan perdagangan dengan leverage, yang dapat mencapai keuntungan tinggi.",home22:"Opsi",home23:"Perdagangan opsi menyediakan strategi lindung nilai fleksibel untuk mengontrol risiko dan memperoleh keuntungan.",home24:"Investasi AI",home25:"Rencanakan dengan Percaya Diri. Investasikan dengan Cerdas. Kurangi Kekhawatiran",home26:"Tingkat Pengembalian Tahunan Tertinggi dalam Sejarah",home27:"Saat ini",home28:"Reguler",home29:"Beli Sekarang",home30:"Semua orang bisa menggunakan mata uang digital",home31:"Dari pengalaman awal perdagangan mata uang digital hingga pembelian pertama produk keuangan, platform akan membantu Anda dengan mudah mendapatkan koin",home32:"Pelajari tentang cryptocurrency",home33:"Pelajari semua tentang cryptocurrency untuk mulai berinvestasi",home34:"Pertanyaan yang Sering Diajukan",home35:"Siap memulai perjalanan kripto Anda?",home36:"Apa itu bursa cryptocurrency?",home37:"Bursa cryptocurrency adalah pasar digital yang memungkinkan pengguna membeli dan menjual cryptocurrency seperti Bitcoin, Ethereum, dan Tether. Bursa Binance adalah bursa kripto terbesar berdasarkan volume perdagangan.",home38:"Produk apa saja yang ditawarkan platform?",home39:"Sebagai platform perdagangan cryptocurrency global terkemuka, platform saat ini melayani lebih dari 150 juta pengguna terdaftar di lebih dari 180 negara/wilayah. Dengan biaya transaksi rendah, platform menawarkan lebih dari 350 cryptocurrency yang dapat diperdagangkan, menjadikannya pilihan utama untuk perdagangan Bitcoin, altcoin, dan aset digital lainnya. <br><br> Di platform, pengguna dapat: <br><br>1. Perdagangkan ratusan cryptocurrency dan pasangan perdagangan.<br><br>2. Beli dan jual cryptocurrency melalui perdagangan spot platform.<br><br>3. Dapatkan bunga cryptocurrency melalui manajemen kekayaan platform",home40:"Bagaimana cara memperdagangkan cryptocurrency di platform",home41:"Di platform, Anda dapat memperdagangkan ratusan cryptocurrency di pasar spot, futures, dan opsi. Untuk memulai perdagangan, pengguna perlu mendaftar akun di platform, menyelesaikan verifikasi identitas, dan deposit/beli cryptocurrency, lalu mereka dapat mulai berdagang.",home42:"Apakah platform ini bursa cryptocurrency yang aman?",home43:"Platform ini berkomitmen menyediakan platform perdagangan yang aman dan terpercaya. Kami memiliki salah satu teknologi keamanan dan tim pemeliharaan paling canggih di dunia, termasuk tim keamanan khusus yang terus bekerja untuk memastikan keamanan aset dan akun Anda. Kami juga telah menjalani verifikasi bukti cadangan independen untuk memastikan semua aset pengguna didukung dengan rasio 1:1.",home44:"Bagaimana cara mengatasi lupa kata sandi login?",home45:"Anda dapat mengklik 'Lupa Kata Sandi' di halaman login, kemudian atur ulang 'Kata Sandi Login'.",home46:"Mengapa Anda perlu Otentikasi Identitas?",home47:"Untuk keamanan dana Anda dan mencegah kegiatan pencucian uang, kami perlu memastikan akun penerima terkait dengan informasi identitas akun saat ini.",home48:"Pasar",home49:"Pasar perdagangan cryptocurrency global mendukung transaksi multi-mata uang, menawarkan keamanan dan efisiensi.",home50:"Akun Saya",home51:"Deposit",home52:"Tarik",home53:"Konversi",home54:"Populer",home55:"Investasikan di Token yang Baru Diterbitkan dan Raih Potensi Keuntungan Tinggi",home56:"Berita",home57:"Mengapa memilih kami?",home58:"Dipercaya oleh jutaan orang",home59:"Jumlah pengguna",home60:"Unit mitra",home61:"Biaya transaksi minimum",home62:"Mitra",home63:"Vol 24h",home64:"Membuka era baru kekayaan digital",home65:"Bertransaksi aman, berinvestasi mudah",home66:"Mulai sekarang",home67:"Trading cerdas, masa depan terhubung",home68:"Trading super cepat, jangan lewatkan peluang",home69:"Aset digital, mudah dijangkau",jianguanzhengshu:"Sertifikat Regulasi",falvzhengmingshu:"Sertifikat Hukum",withdrawNote:"Pemberitahuan Penarikan:<br><br>Waktu pemrosesan penarikan adalah 24 jam<br><br>Setelah mengajukan permintaan penarikan dana, dana akan dibekukan karena penarikan sedang diproses dan sementara disimpan oleh sistem. Ini tidak berarti aset Anda hilang atau ada kelainan.<br><br>Permintaan penarikan token akan dikreditkan dalam 12 jam setelah pengajuan. Jika penarikan token tidak dikreditkan setelah waktu kedatangan yang diharapkan, silakan hubungi layanan pelanggan online.<br><br>Penarikan dalam jumlah besar harus dilakukan oleh anggota VIP kami. Silakan hubungi layanan pelanggan online untuk detailnya."},yingshe:{miaoheyue:"Perdagangan Opsi",miaoheyuejiaoyi:"Perdagangan Opsi",heyuezhanghu:"Akun Perdagangan"},deltax:{company_bylaws:"Peraturan perusahaan",good_standing_certificate:"Sertifikat berdiri baik",about_title:"Tentang Kami",about_text_1:"Kami adalah salah satu platform perdagangan dengan pertumbuhan tercepat di Eropa, dengan kantor di Inggris, Eropa, dan Australia. Kami selalu menempatkan klien di pusat setiap keputusan yang kami buat, mempromosikan perdagangan mereka melalui teknologi intuitif, pendidikan mendalam, dan dukungan yang berdedikasi.",about_text_2:"Misi kami adalah menyediakan alat dan sumber daya yang dibutuhkan trader untuk berdagang dengan percaya diri dan membuat keputusan yang lebih baik. Misi ini telah memenangkan kami berbagai penghargaan dari otoritas industri terkemuka.",stats_title:"Ringkasan Pertumbuhan",stat_global_label:"Operasi Global",stat_global_desc:"Seiring dengan terus bertambahnya kantor global kami, kami bangga dapat melayani klien di 183 negara dan wilayah",stat_global_link:"Pelajari tentang perdagangan",stat_traders_label:"Trader",stat_traders_desc:"Sejak diluncurkan, komunitas trader global kami telah melakukan perdagangan dengan volume lebih dari 53 miliar dolar AS",stat_traders_link:"Lihat berita terbaru",stat_support_label:"Staf Dukungan",stat_support_desc:"Tim layanan pelanggan ramah kami tersedia 24 jam dalam 12 bahasa untuk membantu Anda dengan pertanyaan terkait akun apa pun",stat_support_link:"Dukungan",promise_title:"Komitmen Kami kepada Klien",promise_desc:"Perdagangan adalah keterampilan yang hanya sedikit orang yang benar-benar menguasainya. Namun kami percaya bahwa dengan menggabungkan teknologi inovatif, pendidikan imersif, dan wawasan unik tentang perilaku perdagangan dengan benar, siapa pun dapat mengembangkan keahlian perdagangan di pasar. Baik Anda trader berpengalaman maupun pemula, kami menyediakan alat yang Anda butuhkan untuk meningkatkan pengetahuan dan keterampilan Anda.",promise_customer_name:"Klien Utama",promise_customer_text:"Dibangun oleh trader, kami menerapkan penelitian khusus, ilmu data, dan wawasan unik untuk mengembangkan produk yang menginspirasi klien kami untuk meningkat",promise_innovation_name:"Tidak Pernah Berhenti",promise_innovation_text:"Kami berkomitmen untuk terus mengoptimalkan platform kami guna memberikan pengalaman pengguna yang mulus dan memungkinkan perdagangan yang percaya diri serta keputusan yang lebih baik melalui alat inovatif yang berfokus pada teknologi",promise_transparency_name:"Selalu Transparan",promise_transparency_text:"Kami berupaya menghilangkan hambatan perdagangan dengan menawarkan beberapa harga paling kompetitif di industri, bersama dengan sumber daya pendidikan yang mudah digunakan dan kaya",promise_expertise_name:"Keahlian Terdepan",promise_expertise_text:"Tim internasional kami membawa puluhan tahun teknologi dan keahlian perdagangan, meletakkan dasar untuk platform yang ramah pengguna, berpusat pada teknologi, dan intuitif",expertise_title:"Keahlian Kami",expertise_text_1:"Sebagai pialang yang memenangkan penghargaan, kami diakui oleh klien kami karena pengalaman pengguna yang intuitif dan berbasis teknologi, dukungan pelanggan berkualitas tinggi, serta nilai yang sangat baik. Teknologi adalah inti dari segala yang kami lakukan, menawarkan fitur cerdas seperti data pasar real-time, alat charting canggih, dan aplikasi seluler responsif yang mendukung perdagangan seluler. Tujuan kami adalah memberikan akses tanpa hambatan bagi trader ritel ke instrumen keuangan global.",expertise_text_2:"Kami selalu mencari cara baru untuk membantu klien berdagang dengan percaya diri dan membuat keputusan yang lebih cerdas, menyediakan teknologi terbaru, sumber daya pendidikan mendalam, dan harga kompetitif dalam lingkungan perdagangan yang terus berubah.",expertise_stat_traders:"Trader",expertise_stat_service:"Layanan Pelanggan",expertise_stat_unit_second:"dtk",expertise_stat_speed_label:"Kecepatan eksekusi rata-rata",expertise_stat_indicators:"Indikator teknikal",expertise_footnote:"Berdasarkan data server internal kami dari 2022",awards_title:"Pengakuan Industri",awards_desc_1:"Produk intuitif kami, layanan pelanggan yang berdedikasi, dan inovasi berkelanjutan telah berkali-kali diakui oleh beberapa otoritas terkemuka di industri.",awards_desc_2:"Pada tahun 2023, Deloitte Technology Fast 50 menempatkan kami sebagai salah satu dari 50 perusahaan teknologi dengan pertumbuhan tercepat di Timur Tengah dan Siprus. Berikut adalah beberapa penghargaan terbaru kami:",products_title:"Produk dan Layanan Kami",product_cfd_name:"Perdagangan CFD",product_cfd_desc:"Lakukan long atau short pada forex, indeks, saham, komoditas, dan lainnya, tanpa tanggal kedaluwarsa tetap dan tanpa pajak setem pada saham Inggris",product_platform_name:"Platform Ramah Pengguna",product_platform_desc:"Kami mengutamakan kemudahan penggunaan bagi klien kami, memungkinkan perdagangan melalui desktop, seluler, dan API",product_demo_name:"Akun Demo Perdagangan",product_demo_desc:"Trader dapat mencoba platform kami tanpa risiko dengan dana virtual sambil menyempurnakan strategi perdagangan mereka",product_education_name:"Edukasi",product_education_desc:"Memberikan wawasan mendalam tentang penggerak pasar fundamental dan teknis terbaru untuk membantu trader membuat keputusan yang tepat",product_more:"Selengkapnya",products_footnote:"Perlakuan pajak tergantung pada keadaan individu dan dapat berubah atau berbeda di yurisdiksi di luar Inggris",global_title:"Kantor Global",award_source_good_money:"Good Money Guide",award_source_online_money:"Online Money Awards",award_source_forexbrokers:"ForexBrokers.com",award_source_investment_trends:"Investment Trends",award_source_advfn:"ADVFN",award_source_ft:"Financial Times Investors’ Chronicle",award_good_money_guide:"Aplikasi Perdagangan Terbaik 2023",award_online_money:"Penyedia CFD Terbaik 2023",award_forexbrokers:"Broker dengan Pertumbuhan Tercepat 2023",award_investment_satisfaction:"Kepuasan Klien Secara Keseluruhan 2022",award_investment_value:"Nilai Terbaik untuk Uang 2022",award_advfn:"Broker dengan Pertumbuhan Tercepat 2023",award_ft_investors:"Mendukung Investor Baru 2022"},licai:{zhiyawakuang:"Hasil Cerdas",zhiyawakuangjiaoyi:"Perdagangan Hasil Cerdas"}};export{a as default};
